const std = @import("std");
const c = @import("network.zig");
const p = @import("processes.zig");
const clock = @import("clocks.zig");
pub fn graphEdges(events: []const p.Event, copies: []const p.Copy, messages: []const p.Message,
     processes: []const p.Process) []std.ArrayList(usize) {
    const out = c.alloc(std.ArrayList(usize), events.len);
    @memset(out, .empty);
    for (events, 0..) |event, i| {
        const local = processes[event.process].events.items;
        if (event.local < local.len) c.append(usize, &out[i], local[event.local]);
    }
    for (copies) |copy| if (copy.received) |received| c.append(usize, &out[messages[copy.message].send], received);
    return out;
}
pub fn graphPath(source: usize, target: usize, graph: []const std.ArrayList(usize)) []const usize {
    const parent = c.alloc(?usize, graph.len);
    @memset(parent, null);
    var queue: std.ArrayList(usize) = .empty;
    c.append(usize, &queue, source);
    parent[source] = source;
    var head: usize = 0;
    while (head < queue.items.len and parent[target] == null) : (head += 1) {
        for (graph[queue.items[head]].items) |next| if (parent[next] == null) {
            parent[next] = queue.items[head];
            c.append(usize, &queue, next);
        };
    }
    var out: std.ArrayList(usize) = .empty;
    if (parent[target] == null) return out.items;
    var cursor = target;
    while (true) {
        c.append(usize, &out, cursor);
        if (cursor == source) break;
        cursor = parent[cursor].?;
    }
    std.mem.reverse(usize, out.items);
    return out.items;
}
pub const Concurrency = struct { ordered: i64 = 0, concurrent: i64 = 0, same: i64 = 0, inversions: i64 = 0,
     pairs: [6][6]i64 = [_][6]i64{c.zero} ** 6 };
pub fn concurrency(events: []const p.Event, count: usize) Concurrency {
    var out: Concurrency = .{};
    for (events, 0..) |a, i| for (events[i + 1 ..]) |b| {
        if (clock.relation(a.clock, b.clock, count) == 0) {
            out.concurrent += 1;
            out.same += @intFromBool(a.lamport == b.lamport);
            out.pairs[@min(a.process, b.process)][@max(a.process, b.process)] += 1;
        } else out.ordered += 1;
        if (a.time != b.time and a.lamport != b.lamport and ((a.time < b.time) != (a.lamport < b.lamport))) out.inversions += 1;
    };
    return out;
}
pub const Violation = struct { process: usize, first: usize, second: usize };
pub const Orders = struct { races: std.ArrayList(Violation) = .empty, violations: std.ArrayList(Violation) = .empty,
     fifo: i64 = 0 };
pub fn orders(processes: []const p.Process, copies: []const p.Copy, messages: []const p.Message,
     events: []const p.Event) Orders {
    var out: Orders = .{};
    for (processes, 0..) |process, own| {
        const delivered = process.delivered.items;
        if (delivered.len > 0) for (delivered[0 .. delivered.len - 1], delivered[1..]) |a, b| {
            if (clock.relation(events[messages[copies[a].message].send].clock, events[messages[copies[b].message].send].clock,
                 processes.len) == 0) c.append(Violation, &out.races, .{ .process = own, .first = a,
                 .second = b });
        };
        for (delivered, 0..) |a, i| for (delivered[i + 1 ..]) |b| if (clock.relation(events[messages[copies[b].message].send].clock,
             events[messages[copies[a].message].send].clock, processes.len) == 1) {
            c.append(Violation, &out.violations, .{ .process = own, .first = a, .second = b });
            out.fifo += @intFromBool(copies[a].source == copies[b].source);
        };
    }
    return out;
}
pub const Predicate = struct { cuts: i64 = 0, definite: bool = false };
pub const Enumeration = struct { limits: c.Vec = c.zero, levels: []i64, product: usize = 1,
     consistent: i64 = 0, predicates: []Predicate };
pub fn enumerate(processes: []const p.Process, events: []const p.Event, time: i64, thresholds: []const i64) Enumeration {
    const n = processes.len;
    var out: Enumeration = .{ .levels = undefined, .predicates = c.alloc(Predicate, thresholds.len) };
    @memset(out.predicates, .{});
    var strides = [_]usize{0} ** 6;
    var level_max: usize = 0;
    var initial: i64 = 0;
    var pindex = n;
    while (pindex > 0) {
        pindex -= 1;
        for (processes[pindex].events.items) |index| out.limits[pindex] += @intFromBool(events[index].time <= time);
        strides[pindex] = out.product;
        out.product *= c.u(out.limits[pindex] + 1);
        level_max += c.u(out.limits[pindex]);
        initial += processes[pindex].initial;
    }
    out.levels = c.alloc(i64, level_max + 1);
    @memset(out.levels, 0);
    const consistent = c.alloc(bool, out.product);
    @memset(consistent, false);
    const transit = c.alloc(i64, out.product);
    @memset(transit, 0);
    for (0..out.product) |index| {
        var cut = c.zero;
        var level: usize = 0;
        var balance: i64 = 0;
        for (0..n) |own| {
            cut[own] = c.n(index / strides[own] % c.u(out.limits[own] + 1));
            level += c.u(cut[own]);
            balance += p.balanceAtCut(processes[own], events, cut[own]);
        }
        var good = true;
        for (0..n) |own| if (cut[own] > 0 and !clock.lessEqual(events[processes[own].events.items[c.u(cut[own] - 1)]].clock,
             cut, n)) {
            good = false;
        };
        if (!good) continue;
        consistent[index] = true;
        out.consistent += 1;
        out.levels[level] += 1;
        transit[index] = initial - balance;
        for (thresholds, out.predicates) |threshold, *predicate| predicate.cuts += @intFromBool(transit[index] >= threshold);
    }
    const reachable = c.alloc(bool, out.product);
    for (thresholds, out.predicates) |threshold, *predicate| {
        @memset(reachable, false);
        for (0..out.product) |index| {
            if (!consistent[index] or transit[index] >= threshold) continue;
            if (index == 0) reachable[0] = true;
            for (0..n) |own| if (index / strides[own] % c.u(out.limits[own] + 1) > 0 and reachable[index - strides[own]]) {
                reachable[index] = true;
            };
        }
        predicate.definite = !reachable[out.product - 1];
    }
    return out;
}

const c = @import("network.zig");
pub fn local(lamport: *i64, clock: *c.Vec, own: usize) void {
    lamport.* += 1;
    clock[own] += 1;
}
pub fn receive(lamport: *i64, clock: *c.Vec, own: usize, sent_lamport: i64, sent: c.Vec, count: usize) void {
    lamport.* = @max(lamport.*, sent_lamport) + 1;
    for (0..count) |i| clock[i] = @max(clock[i], sent[i]);
    clock[own] += 1;
}
pub fn lessEqual(first: c.Vec, second: c.Vec, count: usize) bool {
    for (0..count) |i| if (first[i] > second[i]) return false;
    return true;
}
pub fn relation(first: c.Vec, second: c.Vec, count: usize) i64 {
    var equal = true;
    for (0..count) |i| {
        if (first[i] != second[i]) equal = false;
    }
    if (equal) return 0;
    return if (lessEqual(first, second, count)) 1 else if (lessEqual(second, first, count)) -1 else 0;
}
pub fn deliverable(stamp: c.Vec, received: c.Vec, source: usize, count: usize) bool {
    for (0..count) |i| if (if (i == source) stamp[i] != received[i] + 1 else stamp[i] > received[i]) return false;
    return true;
}
pub fn missing(stamp: c.Vec, received: c.Vec, source: usize, count: usize) []const usize {
    var out: @import("std").ArrayList(usize) = .empty;
    for (0..count) |i| if (stamp[i] > received[i] + @as(i64, @intFromBool(i == source))) c.append(usize, &out, i);
    return out.items;
}
pub fn text(vector: []const i64) []const u8 {
    var out: c.Text = .{};
    for (vector, 0..) |value, i| out.add("{s}{d}", .{ if (i > 0) "," else "", value });
    return out.value();
}

const std = @import("std");
const c = @import("network.zig");
const clock = @import("clocks.zig");
const p = @import("processes.zig");
const snap = @import("snapshot.zig");
const analysis = @import("analysis.zig");
const Compare = struct { first: []const u8, second: []const u8 };
const Params = struct {
    seed: i64 = 0,
    end: i64 = 0,
    cutcount: i64 = 0,
    compare: std.ArrayList(Compare) = .empty,
    cuts: std.ArrayList(c.Vec) = .empty,
    predicates: std.ArrayList(i64) = .empty,
};
fn parameters(io: std.Io) !Params {
    var out: Params = .{};
    for (try c.readLines(io, "input/params.txt")) |line| {
        const row = c.words(line);
        if (c.eq(row[0], "SEED")) out.seed = c.number(row[1]) else if (c.eq(row[0], "END")) out.end = c.number(row[1]) else if (c.eq(row[0],
             "CUTCOUNT")) out.cutcount = c.number(row[1]) else if (c.eq(row[0], "COMPARE")) c.append(Compare,
             &out.compare, .{ .first = row[1], .second = row[2] }) else if (c.eq(row[0], "CUT")) {
            var cut = c.zero;
            for (row[1..], 0..) |field, i| cut[i] = c.number(field);
            c.append(c.Vec, &out.cuts, cut);
        } else if (c.eq(row[0], "PREDICATE")) c.append(i64, &out.predicates, c.number(row[1]));
    }
    return out;
}
const Item = struct {
    time: i64,
    process: usize,
    creation: i64 = 0,
    packet: ?usize = null,
    action: ?p.Action = null,
    fn earlier(a: Item, b: Item) bool {
        if (a.time != b.time) return a.time < b.time;
        if (a.process != b.process) return a.process < b.process;
        return a.creation < b.creation;
    }
};
const Timeline = struct { snapshot: bool, process: usize, index: usize, time: i64 };
const Simulation = struct {
    topology: c.Topology,
    scripts: []const p.Script,
    params: Params,
    raw: bool,
    random: c.Random,
    time: i64 = 0,
    creation: i64 = 0,
    processes: []p.Process,
    events: std.ArrayList(p.Event) = .empty,
    messages: std.ArrayList(p.Message) = .empty,
    copies: std.ArrayList(p.Copy) = .empty,
    packets: std.ArrayList(p.Packet) = .empty,
    snapshots: std.ArrayList(*snap.Snapshot) = .empty,
    timeline: std.ArrayList(Timeline) = .empty,
    queue: std.ArrayList(Item) = .empty,
    fn init(topology: c.Topology, scripts: []const p.Script, params: Params, raw: bool) Simulation {
        return .{ .topology = .{ .names = topology.names, .channels = c.dupe(c.Channel, topology.channels) },
             .scripts = scripts, .params = params, .raw = raw, .random = .{ .state = params.seed },
             .processes = p.initialize(scripts) };
    }
    fn enqueue(self: *Simulation, value: Item) void {
        var item = value;
        self.creation += 1;
        item.creation = self.creation;
        c.append(Item, &self.queue, item);
        var index = self.queue.items.len - 1;
        while (index > 0) {
            const parent = (index - 1) / 2;
            if (!Item.earlier(item, self.queue.items[parent])) break;
            self.queue.items[index] = self.queue.items[parent];
            index = parent;
        }
        self.queue.items[index] = item;
    }
    fn dequeue(self: *Simulation) Item {
        const first = self.queue.items[0];
        const last = self.queue.pop().?;
        if (self.queue.items.len > 0) {
            var index: usize = 0;
            while (2 * index + 1 < self.queue.items.len) {
                var child = 2 * index + 1;
                if (child + 1 < self.queue.items.len and Item.earlier(self.queue.items[child + 1],
                     self.queue.items[child])) child += 1;
                if (!Item.earlier(self.queue.items[child], last)) break;
                self.queue.items[index] = self.queue.items[child];
                index = child;
            }
            self.queue.items[index] = last;
        }
        return first;
    }
    fn record(self: *Simulation, own: usize, kind: p.EventKind, peer: ?usize, message: ?usize,
         copy: ?usize, label: []const u8, amount: i64) usize {
        const state = &self.processes[own];
        if (kind == .recv) {
            const sent = self.events.items[self.messages.items[self.copies.items[copy.?].message].send];
            clock.receive(&state.lamport, &state.clock, own, sent.lamport, sent.clock, self.processes.len);
        } else clock.local(&state.lamport, &state.clock, own);
        const index = self.events.items.len;
        c.append(p.Event, &self.events, .{ .process = own, .local = state.events.items.len + 1,
             .time = self.time, .kind = kind, .peer = peer, .message = message, .copy = copy,
             .lamport = state.lamport, .balance = state.balance, .amount = amount, .clock = state.clock,
             .label = label });
        c.append(usize, &state.events, index);
        state.counts[@intFromEnum(kind)] += 1;
        state.minimum = @min(state.minimum, state.balance);
        c.append(Timeline, &self.timeline, .{ .snapshot = false, .process = own, .index = index, .time = self.time });
        return index;
    }
    fn sendPacket(self: *Simulation, source: usize, destination: usize, copy: ?usize, snapshot: ?usize) void {
        const sent_clock = if (copy) |index| self.events.items[self.messages.items[self.copies.items[index].message].send].clock else c.zero;
        const arrival = c.dispatch(&self.topology.channels[source * self.processes.len + destination],
             self.time, snapshot != null, sent_clock, self.processes.len, &self.random);
        const index = self.packets.items.len;
        c.append(p.Packet, &self.packets, .{ .source = source, .destination = destination,
             .sequence = arrival.sequence, .dispatch = self.time, .arrival = arrival.time,
             .copy = copy, .snapshot = snapshot });
        if (copy) |id| self.copies.items[id].packet = index;
        self.enqueue(.{ .time = arrival.time, .process = destination, .packet = index });
    }
    fn recordSnapshot(self: *Simulation, index: usize, own: usize, reason: []const u8) void {
        const snapshot = self.snapshots.items[index];
        snap.recordState(snapshot, own, self.processes[own], self.time, reason);
        c.append(Timeline, &self.timeline, .{ .snapshot = true, .process = own, .index = index, .time = self.time });
        for (0..self.processes.len) |destination| if (destination != own) {
            self.sendPacket(own, destination, null, index);
            snapshot.channels[own * self.processes.len + destination].sent = self.time;
        };
    }
    fn initiate(self: *Simulation, own: usize, name: []const u8) void {
        var index: usize = 0;
        while (index < self.snapshots.items.len and !c.eq(self.snapshots.items[index].name, name)) : (index += 1) {}
        if (index == self.snapshots.items.len) c.append(*snap.Snapshot, &self.snapshots, snap.init(name,
             self.time, self.processes.len));
        if (self.snapshots.items[index].records[own].present) c.append(snap.Ignored, &self.snapshots.items[index].ignored,
             .{ .process = own, .time = self.time }) else self.recordSnapshot(index, own, "initiate");
    }
    fn action(self: *Simulation, own: usize, value: p.Action, sender: ?usize) void {
        if (value.kind == .local) {
            _ = self.record(own, .local, null, null, null, value.argument, 0);
            return;
        }
        if (value.kind == .snapshot) {
            self.initiate(own, value.argument);
            return;
        }
        const state = &self.processes[own];
        const broadcast = value.kind == .broadcast;
        const destination: ?usize = if (broadcast) null else if (c.eq(value.argument, "SENDER")) sender.? else self.topology.index(value.argument);
        const amount = if (value.kind == .transfer) value.amount else 0;
        if (value.kind == .transfer and amount > state.balance) {
            state.refused += 1;
            _ = self.record(own, .nofunds, destination, null, null, "", amount);
            return;
        }
        state.balance -= amount;
        state.out += amount;
        if (broadcast) state.broadcast[own] += 1;
        const message = self.messages.items.len;
        c.append(p.Message, &self.messages, .{ .source = own, .tag = if (broadcast) value.argument else if (value.kind == .transfer) "transfer" else value.tag,
             .amount = amount, .broadcast = broadcast, .stamp = if (broadcast) state.broadcast else c.zero });
        self.messages.items[message].send = self.record(own, if (broadcast) .bcast else .send,
             destination, message, null, "", 0);
        for (0..self.processes.len) |target| if (if (broadcast) target != own else target == destination.?) {
            const copy = self.copies.items.len;
            c.append(p.Copy, &self.copies, .{ .message = message, .source = own, .destination = target });
            c.append(usize, &self.messages.items[message].copies, copy);
            self.sendPacket(own, target, copy, null);
        };
    }
    fn deliver(self: *Simulation, index: usize) void {
        const copy = self.copies.items[index];
        const message = self.messages.items[copy.message];
        const state = &self.processes[copy.destination];
        if (message.broadcast) state.broadcast[copy.source] += 1;
        state.balance += message.amount;
        state.in += message.amount;
        self.copies.items[index].delivery = self.time;
        self.copies.items[index].received = self.record(copy.destination, .recv, copy.source,
             copy.message, index, "", 0);
        c.append(usize, &state.delivered, index);
        for (self.scripts[copy.destination].on.items) |rule| if (c.eq(rule.tag, message.tag)) self.action(copy.destination,
             rule.action, copy.source);
    }
    fn canDeliver(self: *const Simulation, index: usize) bool {
        const copy = self.copies.items[index];
        return clock.deliverable(self.messages.items[copy.message].stamp, self.processes[copy.destination].broadcast,
             copy.source, self.processes.len);
    }
    fn accept(self: *Simulation, index: usize) void {
        const packet = self.packets.items[index];
        const state = &self.processes[packet.destination];
        state.next[packet.source] += 1;
        if (packet.snapshot) |id| {
            const snapshot = self.snapshots.items[id];
            if (!snapshot.records[packet.destination].present) self.recordSnapshot(id, packet.destination,
                 c.fmt("marker {s}", .{self.topology.names[packet.source]}));
            snap.acceptMarker(snapshot, packet.source, packet.destination, self.time, self.processes.len);
            return;
        }
        for (self.snapshots.items) |snapshot| {
            const channel = &snapshot.channels[packet.source * self.processes.len + packet.destination];
            if (snapshot.records[packet.destination].present and channel.accepted == null) c.append(usize,
                 &channel.copies, packet.copy.?);
        }
        const copy = self.copies.items[packet.copy.?];
        const message = self.messages.items[copy.message];
        if (self.raw or !message.broadcast) {
            self.deliver(packet.copy.?);
            return;
        }
        if (self.canDeliver(packet.copy.?)) {
            self.deliver(packet.copy.?);
            while (true) {
                var ready: ?usize = null;
                for (state.hold.items, 0..) |candidate, i| if (self.canDeliver(candidate)) {
                    ready = i;
                    break;
                };
                const position = ready orelse break;
                const candidate = state.hold.orderedRemove(position);
                self.deliver(candidate);
            }
        } else {
            self.copies.items[packet.copy.?].causal_wait = true;
            self.copies.items[packet.copy.?].missing = clock.missing(message.stamp, state.broadcast,
                 copy.source, self.processes.len);
            c.append(usize, &state.hold, packet.copy.?);
        }
    }
    fn arrival(self: *Simulation, index: usize) void {
        const packet = self.packets.items[index];
        const state = &self.processes[packet.destination];
        if (self.raw) self.accept(index) else if (packet.sequence != state.next[packet.source]) {
            c.append(usize, &state.reorder[packet.source], index);
            self.topology.channels[packet.source * self.processes.len + packet.destination].buffered += 1;
            if (packet.copy) |copy| self.copies.items[copy].fifo_wait = true;
        } else {
            self.accept(index);
            while (true) {
                const buffer = &state.reorder[packet.source];
                var ready: ?usize = null;
                for (buffer.items, 0..) |candidate, i| if (self.packets.items[candidate].sequence == state.next[packet.source]) {
                    ready = i;
                    break;
                };
                const position = ready orelse break;
                const following = buffer.orderedRemove(position);
                self.accept(following);
            }
        }
        var held = state.hold.items.len;
        for (state.reorder) |buffer| held += buffer.items.len;
        state.max_held = @max(state.max_held, held);
    }
    fn run(self: *Simulation) void {
        for (p.expand(self.scripts, self.params.end)) |scheduled| self.enqueue(.{ .time = scheduled.time,
             .process = scheduled.process, .action = scheduled.action });
        while (self.queue.items.len > 0 and self.queue.items[0].time <= self.params.end) {
            const item = self.dequeue();
            self.time = item.time;
            if (item.packet) |index| self.arrival(index) else self.action(item.process, item.action.?, null);
        }
    }
    fn eventName(self: *const Simulation, index: usize) []const u8 {
        const event = self.events.items[index];
        return c.fmt("{s}.{d}", .{ self.topology.names[event.process], event.local });
    }
    fn copyName(self: *const Simulation, index: usize) []const u8 {
        const copy = self.copies.items[index];
        return c.fmt("m{d}->{s}", .{ copy.message + 1, self.topology.names[copy.destination] });
    }
    fn processNames(self: *const Simulation, indices: []const usize) []const u8 {
        var out: c.Text = .{};
        for (indices, 0..) |index, i| out.add("{s}{s}", .{ if (i > 0) "," else "", self.topology.names[index] });
        return out.value();
    }
    fn initial(self: *const Simulation) i64 {
        var out: i64 = 0;
        for (self.processes) |state| out += state.initial;
        return out;
    }
    fn delivered(self: *const Simulation) usize {
        var out: usize = 0;
        for (self.copies.items) |copy| {
            if (copy.received != null) out += 1;
        }
        return out;
    }
    fn cutDetails(self: *const Simulation, cut: c.Vec) snap.Details {
        return snap.details(cut, self.processes, self.events.items, self.messages.items, self.copies.items);
    }
    fn vector(self: *const Simulation, value: c.Vec) []const u8 {
        return clock.text(value[0..self.processes.len]);
    }
};
fn yes(value: bool) []const u8 {
    return if (value) "yes" else "no";
}
fn relationName(value: i64) []const u8 {
    return if (value > 0) "->" else if (value < 0) "<-" else "||";
}
fn messageName(index: usize) []const u8 {
    return c.fmt("m{d}", .{index + 1});
}
fn save(io: std.Io, name: []const u8, lines: c.Lines) !void {
    var out: c.Text = .{};
    for (lines.data.items) |line| out.add("{s}\n", .{line});
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = c.fmt("output/{s}", .{name}), .data = out.value() });
}
fn ranges(s: *const Simulation, path: []const usize) []const u8 {
    var out: c.Text = .{};
    var i: usize = 0;
    while (i < path.len) {
        var j = i;
        while (j + 1 < path.len and s.events.items[path[j + 1]].process == s.events.items[path[j]].process and s.events.items[path[j + 1]].local == s.events.items[path[j]].local + 1) : (j += 1) {}
        out.add("{s}{s}", .{ if (i > 0) " " else "", s.eventName(path[i]) });
        if (j > i) out.add("-{d}", .{s.events.items[path[j]].local});
        i = j + 1;
    }
    return out.value();
}
fn traceReport(s: *const Simulation) c.Lines {
    const types = [_][]const u8{ "LOCAL", "NOFUNDS", "SEND", "BCAST", "RECV" };
    var out: c.Lines = .{};
    for (s.events.items, 0..) |event, i| {
        var detail: c.Text = .{};
        if (event.kind == .local) detail.add("{s}", .{event.label}) else if (event.kind == .nofunds) detail.add("to {s} amount {d} balance {d}",
             .{ s.topology.names[event.peer.?], event.amount, event.balance }) else {
            const message = s.messages.items[event.message.?];
            detail.add("{s}", .{messageName(event.message.?)});
            if (event.kind == .send) detail.add(" to {s}", .{s.topology.names[event.peer.?]}) else if (event.kind == .recv) detail.add(" from {s}",
                 .{s.topology.names[event.peer.?]});
            detail.add(" tag {s}", .{message.tag});
            if (c.eq(message.tag, "transfer")) detail.add(" amount {d} balance {d}", .{ message.amount,
                 event.balance });
        }
        out.add("{d} t={d} {s} {s} {s} L={d} V={s}", .{ i + 1, event.time, s.eventName(i),
             types[@intFromEnum(event.kind)], detail.value(), event.lamport, s.vector(event.clock) });
    }
    out.add("SUMMARY events {d} messages {d} copies {d} delivered {d} undelivered {d} draws {d}",
         .{ s.events.items.len, s.messages.items.len, s.copies.items.len, s.delivered(), s.copies.items.len - s.delivered(),
         s.random.draws });
    for (s.processes, 0..) |state, own| out.add("FINAL {s} events {d} L={d} V={s} B={s} balance {d} in {d} out {d} refused {d} min {d}",
         .{ s.topology.names[own], state.events.items.len, state.lamport, s.vector(state.clock),
         s.vector(state.broadcast), state.balance, state.in, state.out, state.refused, state.minimum });
    for (s.processes, 0..) |state, own| out.add("COUNTS {s} local {d} nofunds {d} send {d} bcast {d} recv {d}",
         .{ s.topology.names[own], state.counts[0], state.counts[1], state.counts[2], state.counts[3],
         state.counts[4] });
    return out;
}
fn copyDetails(s: *const Simulation, index: usize) []const u8 {
    const copy = s.copies.items[index];
    const message = s.messages.items[copy.message];
    return c.fmt("m{d} from {s} {s} tag {s} sent {d}", .{ copy.message + 1, s.topology.names[copy.source],
         if (message.broadcast) "BCAST" else "P2P", message.tag, s.events.items[message.send].time });
}
fn broadcastList(s: *const Simulation, own: usize) []const usize {
    var out: std.ArrayList(usize) = .empty;
    for (s.processes[own].events.items) |index| {
        const event = s.events.items[index];
        if (event.kind == .bcast or (event.kind == .recv and s.messages.items[event.message.?].broadcast)) c.append(usize,
             &out, event.message.?);
    }
    return out.items;
}
const Tag = struct {
    name: []const u8,
    copies: i64 = 0,
    delivered: i64 = 0,
    latency: i64 = 0,
    maximum: i64 = 0,
    fn less(_: void, a: Tag, b: Tag) bool {
        return std.mem.lessThan(u8, a.name, b.name);
    }
};
fn deliveryReport(s: *const Simulation) c.Lines {
    var out: c.Lines = .{};
    const broadcasts = c.alloc([]const usize, s.processes.len);
    for (s.processes, 0..) |state, own| {
        out.add("PROCESS {s}", .{s.topology.names[own]});
        var counts = [_]i64{0} ** 4;
        var total_wait: i64 = 0;
        var max_wait: i64 = 0;
        for (state.delivered.items, 0..) |index, i| {
            const copy = s.copies.items[index];
            const packet = s.packets.items[copy.packet];
            const mode = @as(usize, @intFromBool(copy.fifo_wait)) + 2 * @as(usize, @intFromBool(copy.causal_wait));
            counts[mode] += 1;
            const wait = copy.delivery - packet.arrival;
            total_wait += wait;
            max_wait = @max(max_wait, wait);
            const mode_text = if (mode == 0) "direct" else if (mode == 1) "fifo" else c.fmt("{s} {s}",
                 .{ if (mode == 2) "causal" else "fifo+causal", s.processNames(copy.missing) });
            out.add("{d} {s} arrived {d} delivered {d} wait {d} {s}", .{ i + 1, copyDetails(s,
                 index), packet.arrival, copy.delivery, wait, mode_text });
        }
        for (s.copies.items, 0..) |copy, i| if (copy.destination == own and copy.received == null and s.packets.items[copy.packet].arrival <= s.params.end) out.add("HELD {s} arrived {d} {s}",
             .{ copyDetails(s, i), s.packets.items[copy.packet].arrival, if (copy.causal_wait) c.fmt("causal {s}",
             .{s.processNames(copy.missing)}) else "fifo" });
        for (s.copies.items, 0..) |copy, i| if (copy.destination == own and s.packets.items[copy.packet].arrival > s.params.end) out.add("TRANSIT {s} arrival {d}",
             .{ copyDetails(s, i), s.packets.items[copy.packet].arrival });
        out.add("TOTAL delivered {d} direct {d} fifo {d} causal {d} both {d} wait {d} max_wait {d} max_held {d}",
             .{ state.delivered.items.len, counts[0], counts[1], counts[2], counts[3], total_wait,
             max_wait, state.max_held });
        broadcasts[own] = broadcastList(s, own);
        var list: c.Text = .{};
        for (broadcasts[own]) |message| list.add(" m{d}", .{message + 1});
        out.add("BCASTS{s}", .{if (list.value().len == 0) " none" else list.value()});
    }
    for (0..s.processes.len) |source| for (0..s.processes.len) |destination| if (source != destination) {
        const channel = s.topology.channels[source * s.processes.len + destination];
        out.add("CHANNEL {s}->{s} {s} {s} messages {d} markers {d} buffered {d} max_delay {d} entries {d}",
             .{ s.topology.names[source], s.topology.names[destination], if (channel.fifo) "FIFO" else "NONFIFO",
             c.delayText(channel), channel.messages, channel.markers, channel.buffered, channel.max_delay,
             channel.entries });
    };
    var tags: std.ArrayList(Tag) = .empty;
    for (s.copies.items) |copy| {
        const message = s.messages.items[copy.message];
        var index: usize = 0;
        while (index < tags.items.len and !c.eq(tags.items[index].name, message.tag)) : (index += 1) {}
        if (index == tags.items.len) c.append(Tag, &tags, .{ .name = message.tag });
        const tag = &tags.items[index];
        tag.copies += 1;
        if (copy.received != null) {
            tag.delivered += 1;
            const latency = copy.delivery - s.events.items[message.send].time;
            tag.latency += latency;
            tag.maximum = @max(tag.maximum, latency);
        }
    }
    std.mem.sort(Tag, tags.items, {}, Tag.less);
    for (tags.items) |tag| out.add("TAG {s} copies {d} delivered {d} latency {d} max {d}",
         .{ tag.name, tag.copies, tag.delivered, tag.latency, tag.maximum });
    var messages: std.ArrayList(usize) = .empty;
    for (s.messages.items, 0..) |message, i| if (message.broadcast) {
        c.append(usize, &messages, i);
        var stable = true;
        var time: i64 = 0;
        for (message.copies.items) |index| {
            const copy = s.copies.items[index];
            stable = stable and copy.received != null;
            if (copy.received != null) time = @max(time, copy.delivery);
        }
        out.add("STABLE m{d} {s} tag {s} sent {d} stable {s}", .{ i + 1, s.topology.names[message.source],
             message.tag, s.events.items[message.send].time, if (stable) c.fmt("{d}", .{time}) else "none" });
    };
    var disagreements: i64 = 0;
    for (messages.items, 0..) |a, i| for (messages.items[i + 1 ..]) |b| {
        var earlier: std.ArrayList(usize) = .empty;
        var later: std.ArrayList(usize) = .empty;
        for (broadcasts, 0..) |list, own| {
            var x: ?usize = null;
            var y: ?usize = null;
            for (list, 0..) |message, j| {
                if (message == a) x = j;
                if (message == b) y = j;
            }
            if (x != null and y != null) {
                if (x.? < y.?) c.append(usize, &earlier, own) else c.append(usize, &later, own);
            }
        }
        if (earlier.items.len > 0 and later.items.len > 0) {
            disagreements += 1;
            out.add("DISAGREE m{d} m{d} {s} {s}", .{ a + 1, b + 1, s.processNames(earlier.items),
                 s.processNames(later.items) });
        }
    };
    out.add("DISAGREEMENTS {d}", .{disagreements});
    return out;
}
fn verdict(s: *const Simulation, details: snap.Details) []const u8 {
    var out: c.Text = .{};
    out.add("{s}", .{yes(details.orphans.items.len == 0)});
    for (details.orphans.items) |index| out.add(" {s}", .{s.copyName(index)});
    return out.value();
}
fn snapshotReport(s: *const Simulation, raw: *const Simulation) c.Lines {
    var out: c.Lines = .{};
    const n = s.processes.len;
    for (s.snapshots.items) |snapshot| {
        out.add("SNAPSHOT {s} started {d} completed {d}", .{ snapshot.name, snapshot.start, snapshot.complete });
        var balances: i64 = 0;
        var channel_money: i64 = 0;
        var recorded: std.ArrayList(usize) = .empty;
        var pending: std.ArrayList(usize) = .empty;
        for (snapshot.records, 0..) |record, own| {
            balances += record.balance;
            var list: c.Text = .{};
            for (record.pending) |index| {
                list.add(" m{d}", .{s.copies.items[index].message + 1});
                c.append(usize, &pending, index);
            }
            out.add("RECORD {s} t={d} {s} balance {d} L={d} V={s} pending{s}", .{ s.topology.names[own],
                 record.time, record.reason, record.balance, record.lamport, s.vector(record.clock),
                 if (list.value().len == 0) " none" else list.value() });
        }
        for (0..n) |source| for (0..n) |destination| if (source != destination) {
            const channel = snapshot.channels[source * n + destination];
            var list: c.Text = .{};
            for (channel.copies.items) |index| {
                const message = s.messages.items[s.copies.items[index].message];
                c.append(usize, &recorded, index);
                channel_money += message.amount;
                list.add(" m{d}", .{s.copies.items[index].message + 1});
                if (message.amount > 0) list.add(":{d}", .{message.amount});
            }
            out.add("CHANNEL {s}->{s} marker {d} {d} state{s}", .{ s.topology.names[source],
                 s.topology.names[destination], channel.sent, channel.accepted.?, if (list.value().len == 0) " empty" else list.value() });
        };
        for (snapshot.ignored.items) |ignored| out.add("IGNORED {s} t={d}", .{ s.topology.names[ignored.process],
             ignored.time });
        const cut = snap.cut(snapshot);
        const details = s.cutDetails(cut);
        var vector_good = true;
        for (snapshot.records) |record| {
            if (!clock.lessEqual(record.clock, cut, n)) vector_good = false;
        }
        out.add("CUT {s} consistent {s} vector {s}", .{ s.vector(cut), verdict(s, details), yes(vector_good) });
        var all: std.ArrayList(usize) = .empty;
        for (recorded.items) |index| c.append(usize, &all, index);
        for (pending.items) |index| c.append(usize, &all, index);
        const transit = c.dupe(usize, details.transit.items);
        std.mem.sort(usize, all.items, {}, std.sort.asc(usize));
        std.mem.sort(usize, transit, {}, std.sort.asc(usize));
        out.add("TRANSIT channels {d} pending {d} cut {d} match {s}", .{ recorded.items.len,
             pending.items.len, transit.len, yes(std.mem.eql(usize, all.items, transit)) });
        out.add("MONEY balances {d} channels {d} total {d} initial {d} conserved {s}", .{ balances,
             channel_money, balances + channel_money, s.initial(), yes(balances + channel_money == s.initial()) });
    }
    for (raw.snapshots.items) |snapshot| {
        const cut = snap.cut(snapshot);
        const details = raw.cutDetails(cut);
        var money: i64 = 0;
        for (snapshot.records) |record| money += record.balance;
        for (snapshot.channels) |channel| for (channel.copies.items) |index| {
            money += raw.messages.items[raw.copies.items[index].message].amount;
        };
        out.add("RAW {s} completed {d} cut {s} consistent {s} money {d} conserved {s}", .{ snapshot.name,
             snapshot.complete, raw.vector(cut), verdict(raw, details), money, yes(money == raw.initial()) });
    }
    return out;
}
fn findEvent(s: *const Simulation, name: []const u8) usize {
    const dot = std.mem.indexOfScalar(u8, name, '.').?;
    const own = s.topology.index(name[0..dot]);
    return s.processes[own].events.items[c.u(c.number(name[dot + 1 ..]) - 1)];
}
fn longestChain(s: *const Simulation) []const usize {
    var out: std.ArrayList(usize) = .empty;
    if (s.events.items.len == 0) return out.items;
    var current: usize = 0;
    for (s.events.items, 0..) |event, i| if (event.lamport > s.events.items[current].lamport) {
        current = i;
    };
    while (true) {
        c.append(usize, &out, current);
        const event = s.events.items[current];
        if (event.lamport <= 1) break;
        const sender: ?usize = if (event.kind == .recv) s.messages.items[s.copies.items[event.copy.?].message].send else null;
        current = if (sender != null and s.events.items[sender.?].lamport == event.lamport - 1) sender.? else s.processes[event.process].events.items[event.local - 2];
    }
    std.mem.reverse(usize, out.items);
    return out.items;
}
fn analysisReport(s: *const Simulation, raw: *const Simulation) c.Lines {
    var out: c.Lines = .{};
    const n = s.processes.len;
    const graph = analysis.graphEdges(s.events.items, s.copies.items, s.messages.items, s.processes);
    for (s.params.compare.items) |comparison| {
        const a = findEvent(s, comparison.first);
        const b = findEvent(s, comparison.second);
        const e = s.events.items[a];
        const f = s.events.items[b];
        const rel = clock.relation(e.clock, f.clock, n);
        var path = analysis.graphPath(a, b, graph);
        var graph_relation: i64 = if (path.len > 0) 1 else 0;
        if (path.len == 0) {
            path = analysis.graphPath(b, a, graph);
            if (path.len > 0) graph_relation = -1;
        }
        out.add("COMPARE {s} {s} {s} L={d},{d} graph {s} agree {s}", .{ comparison.first, relationName(rel),
             comparison.second, e.lamport, f.lamport, relationName(graph_relation), yes(rel == graph_relation) });
        if (path.len > 0) {
            var messages: i64 = 0;
            for (path[1..], path[0 .. path.len - 1]) |x, y| messages += @intFromBool(s.events.items[x].process != s.events.items[y].process);
            out.add("PATH length {d} messages {d} {s}", .{ path.len, messages, ranges(s, path) });
        }
        for ([_]usize{ a, b }) |index| {
            const event = s.events.items[index];
            var future = c.zero;
            for (s.events.items) |candidate| if (candidate.clock[event.process] < c.n(event.local)) {
                future[candidate.process] += 1;
            };
            out.add("WINDOW {s} past {s} future {s}", .{ s.eventName(index), s.vector(event.clock), s.vector(future) });
        }
    }
    const counts = analysis.concurrency(s.events.items, n);
    const event_count = c.n(s.events.items.len);
    out.add("CONCURRENCY events {d} pairs {d} ordered {d} concurrent {d} same_lamport {d} inversions {d}",
         .{ event_count, @divTrunc(event_count * (event_count - 1), 2), counts.ordered, counts.concurrent,
         counts.same, counts.inversions });
    for (0..n) |a| for (a + 1..n) |b| out.add("PAIR {s} {s} {d}", .{ s.topology.names[a], s.topology.names[b],
         counts.pairs[a][b] });
    const chain = longestChain(s);
    out.add("CHAIN length {d} {s}", .{ chain.len, ranges(s, chain) });
    const ordered = analysis.orders(s.processes, s.copies.items, s.messages.items, s.events.items);
    for (ordered.races.items) |value| {
        const a = s.copies.items[value.first];
        const b = s.copies.items[value.second];
        out.add("RACE {s} m{d} {s} m{d} {s}", .{ s.topology.names[value.process], a.message + 1,
             s.topology.names[a.source], b.message + 1, s.topology.names[b.source] });
    }
    out.add("RACES {d}", .{ordered.races.items.len});
    for (ordered.violations.items) |value| {
        const a = s.copies.items[value.first];
        const b = s.copies.items[value.second];
        out.add("VIOLATION {s} m{d} {s} overtook m{d} {s}", .{ s.topology.names[value.process],
             a.message + 1, s.topology.names[a.source], b.message + 1, s.topology.names[b.source] });
    }
    out.add("VIOLATIONS causal {d} fifo {d}", .{ ordered.violations.items.len, ordered.fifo });
    const raw_ordered = analysis.orders(raw.processes, raw.copies.items, raw.messages.items, raw.events.items);
    out.add("RAW events {d} delivered {d} causal {d} fifo {d}", .{ raw.events.items.len, raw.delivered(),
         raw_ordered.violations.items.len, raw_ordered.fifo });
    for (s.params.cuts.items) |cut| {
        const details = s.cutDetails(cut);
        var status: c.Text = .{};
        status.add("{s}", .{if (details.orphans.items.len == 0) "consistent" else "inconsistent orphans"});
        for (details.orphans.items) |index| status.add(" {s}", .{s.copyName(index)});
        out.add("CUT {s} {s} transit {d} money {d} initial {d}", .{ s.vector(cut), status.value(),
             details.transit.items.len, details.money, s.initial() });
    }
    const cuts = analysis.enumerate(s.processes, s.events.items, s.params.cutcount, s.params.predicates.items);
    out.add("CUTCOUNT t={d} events {s} product {d} consistent {d}", .{ s.params.cutcount, s.vector(cuts.limits),
         cuts.product, cuts.consistent });
    var levels: c.Text = .{};
    levels.add("LEVELS", .{});
    for (cuts.levels) |value| levels.add(" {d}", .{value});
    out.add("{s}", .{levels.value()});
    for (s.params.predicates.items, cuts.predicates) |threshold, predicate| out.add("PREDICATE transit>={d} cuts {d} possibly {s} definitely {s}",
         .{ threshold, predicate.cuts, yes(predicate.cuts > 0), yes(predicate.definite) });
    return out;
}
fn writeAt(row: *std.ArrayList(u8), position: usize, text: []const u8) void {
    while (row.items.len < position + text.len) c.append(u8, row, ' ');
    @memcpy(row.items[position .. position + text.len], text);
}
fn trimmed(row: *std.ArrayList(u8)) []const u8 {
    while (row.items.len > 0 and row.items[row.items.len - 1] == ' ') _ = row.pop();
    return row.items;
}
fn diagramHeader(s: *const Simulation, kind: u8) []const u8 {
    var row: std.ArrayList(u8) = .empty;
    writeAt(&row, 0, c.fmt("    {c}", .{kind}));
    for (s.topology.names, 0..) |name, own| writeAt(&row, 6 + 8 * own, name);
    return trimmed(&row);
}
fn diagramLine(s: *const Simulation, own: usize, value: i64, kind: p.EventKind, message: ?usize,
     source: ?usize, snapshot: []const u8) []const u8 {
    var row: std.ArrayList(u8) = .empty;
    writeAt(&row, 0, c.fmt("{d: >5} ", .{value}));
    for (0..s.processes.len) |index| writeAt(&row, 6 + 8 * index, "|");
    const position = 6 + 8 * own;
    if (snapshot.len > 0) {
        row.items[position] = '#';
        writeAt(&row, position + 1, snapshot);
    } else if (kind == .local) row.items[position] = '*' else if (kind == .nofunds) row.items[position] = 'x' else if (kind == .send or kind == .bcast) {
        row.items[position] = if (kind == .send) 'S' else 'B';
        writeAt(&row, position + 1, messageName(message.?));
    } else {
        row.items[position] = 'R';
        const origin = 6 + 8 * source.?;
        const first = @min(origin, position);
        const last = @max(origin, position);
        for (first + 1..last) |index| row.items[index] = if ((index - 6) % 8 == 0) '+' else '-';
        if (origin < position) row.items[last - 1] = '>' else row.items[first + 1] = '<';
        writeAt(&row, first + 2, messageName(message.?));
    }
    return trimmed(&row);
}
fn diagramReport(s: *const Simulation) c.Lines {
    var out: c.Lines = .{};
    out.add("{s}", .{diagramHeader(s, 't')});
    for (s.timeline.items) |item| {
        if (item.snapshot) out.add("{s}", .{diagramLine(s, item.process, item.time, .local,
             null, null, s.snapshots.items[item.index].name)}) else {
            const event = s.events.items[item.index];
            out.add("{s}", .{diagramLine(s, event.process, event.time, event.kind, event.message, event.peer, "")});
        }
    }
    out.add("{s}", .{diagramHeader(s, 'L')});
    const ordered = c.alloc(usize, s.events.items.len);
    for (ordered, 0..) |*index, i| index.* = i;
    const CompareEvents = struct {
        fn less(events: []const p.Event, a: usize, b: usize) bool {
            return if (events[a].lamport != events[b].lamport) events[a].lamport < events[b].lamport else events[a].process < events[b].process;
        }
    };
    std.mem.sort(usize, ordered, @as([]const p.Event, s.events.items), CompareEvents.less);
    for (ordered) |index| {
        const event = s.events.items[index];
        out.add("{s}", .{diagramLine(s, event.process, event.lamport, event.kind, event.message, event.peer, "")});
    }
    return out;
}
pub fn main(init: std.process.Init) !void {
    var arena = std.heap.ArenaAllocator.init(init.gpa);
    defer arena.deinit();
    c.allocator = arena.allocator();
    const io = init.io;
    const topology = try c.load(io);
    const scripts = try p.load(io, topology);
    const params = try parameters(io);
    var main_run = Simulation.init(topology, scripts, params, false);
    var raw_run = Simulation.init(topology, scripts, params, true);
    main_run.run();
    raw_run.run();
    try std.Io.Dir.cwd().createDirPath(io, "output");
    try save(io, "trace.txt", traceReport(&main_run));
    try save(io, "deliveries.txt", deliveryReport(&main_run));
    try save(io, "snapshots.txt", snapshotReport(&main_run, &raw_run));
    try save(io, "analysis.txt", analysisReport(&main_run, &raw_run));
    try save(io, "diagram.txt", diagramReport(&main_run));
}

const std = @import("std");
pub var allocator: std.mem.Allocator = undefined;
pub fn alloc(comptime T: type, count: usize) []T {
    return allocator.alloc(T, count) catch @panic("allocation failed");
}
pub fn create(comptime T: type, value: T) *T {
    const out = allocator.create(T) catch @panic("allocation failed");
    out.* = value;
    return out;
}
pub fn dupe(comptime T: type, values: []const T) []T {
    return allocator.dupe(T, values) catch @panic("allocation failed");
}
pub fn append(comptime T: type, list: *std.ArrayList(T), value: T) void {
    list.append(allocator, value) catch @panic("allocation failed");
}
pub fn fmt(comptime pattern: []const u8, args: anytype) []const u8 {
    return std.fmt.allocPrint(allocator, pattern, args) catch @panic("allocation failed");
}
pub fn n(value: anytype) i64 {
    return @intCast(value);
}
pub fn u(value: i64) usize {
    return @intCast(value);
}
pub fn eq(a: []const u8, b: []const u8) bool {
    return std.mem.eql(u8, a, b);
}
pub fn number(value: []const u8) i64 {
    return std.fmt.parseInt(i64, value, 10) catch unreachable;
}
pub fn split(value: []const u8, delimiter: u8) []const []const u8 {
    var out: std.ArrayList([]const u8) = .empty;
    var fields = std.mem.splitScalar(u8, value, delimiter);
    while (fields.next()) |field| append([]const u8, &out, field);
    return out.items;
}
pub fn words(value: []const u8) []const []const u8 {
    var out: std.ArrayList([]const u8) = .empty;
    for (split(value, ' ')) |field| if (field.len > 0) append([]const u8, &out, field);
    return out.items;
}
pub const Text = struct {
    data: std.ArrayList(u8) = .empty,
    pub fn add(self: *Text, comptime pattern: []const u8, args: anytype) void {
        self.data.appendSlice(allocator, fmt(pattern, args)) catch @panic("allocation failed");
    }
    pub fn value(self: Text) []const u8 {
        return self.data.items;
    }
};
pub const Lines = struct {
    data: std.ArrayList([]const u8) = .empty,
    pub fn add(self: *Lines, comptime pattern: []const u8, args: anytype) void {
        append([]const u8, &self.data, fmt(pattern, args));
    }
    pub fn extend(self: *Lines, lines: Lines) void {
        for (lines.data.items) |line| self.add("{s}", .{line});
    }
};
pub fn readLines(io: std.Io, path: []const u8) ![]const []const u8 {
    const value = try std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .unlimited);
    const lines = split(value, '\n');
    return lines[0 .. lines.len - 1];
}
pub const Vec = [6]i64;
pub const zero: Vec = .{ 0, 0, 0, 0, 0, 0 };
pub const Random = struct {
    state: i64,
    draws: i64 = 0,
    pub fn draw(self: *Random) i64 {
        self.state = @mod(48271 * self.state, 2147483647);
        self.draws += 1;
        return self.state;
    }
};
pub const Channel = struct { source: usize = 0, destination: usize = 0, minimum: i64 = 0, maximum: i64 = 0,
     sequence: i64 = 0, last_arrival: i64 = 0, messages: i64 = 0, markers: i64 = 0, buffered: i64 = 0,
     max_delay: i64 = 0, entries: i64 = 0, fifo: bool = false, previous: Vec = zero };
pub const Topology = struct {
    names: []const []const u8,
    channels: []Channel,
    pub fn index(self: Topology, name: []const u8) usize {
        for (self.names, 0..) |value, i| if (eq(name, value)) return i;
        unreachable;
    }
};
pub fn load(io: std.Io) !Topology {
    const lines = try readLines(io, "input/topology.txt");
    const header = words(lines[0]);
    const names = header[1..];
    const channels = alloc(Channel, names.len * names.len);
    @memset(channels, .{});
    const out: Topology = .{ .names = names, .channels = channels };
    for (lines[1..]) |line| {
        const row = words(line);
        const source = out.index(row[1]);
        const destination = out.index(row[2]);
        channels[source * names.len + destination] = .{ .source = source, .destination = destination,
             .minimum = number(row[4]), .maximum = number(row[row.len - 1]), .fifo = eq(row[3],
             "FIFO") };
    }
    return out;
}
pub const Arrival = struct { sequence: i64, time: i64 };
pub fn dispatch(channel: *Channel, time: i64, marker: bool, clock: Vec, count: usize, random: *Random) Arrival {
    channel.sequence += 1;
    const delay = channel.minimum + (if (channel.minimum == channel.maximum) @as(i64, 0) else @mod(random.draw(),
         channel.maximum - channel.minimum + 1));
    var arrival = time + delay;
    if (channel.fifo) arrival = @max(arrival, channel.last_arrival);
    channel.last_arrival = @max(channel.last_arrival, arrival);
    channel.max_delay = @max(channel.max_delay, arrival - time);
    if (marker) channel.markers += 1 else {
        channel.messages += 1;
        for (0..count) |i| channel.entries += @intFromBool(clock[i] != channel.previous[i]);
        channel.previous = clock;
    }
    return .{ .sequence = channel.sequence, .time = arrival };
}
pub fn delayText(channel: Channel) []const u8 {
    return if (channel.minimum == channel.maximum) fmt("{d}", .{channel.minimum}) else fmt("{d}-{d}",
         .{ channel.minimum, channel.maximum });
}

const std = @import("std");
const c = @import("network.zig");
pub const ActionKind = enum { local, send, transfer, broadcast, snapshot };
pub const Action = struct { kind: ActionKind, argument: []const u8, tag: []const u8 = "", amount: i64 = 0 };
pub const Timed = struct { start: i64, period: i64, action: Action };
pub const Rule = struct { tag: []const u8, action: Action };
pub const Script = struct { balance: i64 = 0, at: std.ArrayList(Timed) = .empty, on: std.ArrayList(Rule) = .empty };
pub const Process = struct { initial: i64 = 0, balance: i64 = 0, lamport: i64 = 0, in: i64 = 0,
     out: i64 = 0, refused: i64 = 0, minimum: i64 = 0, clock: c.Vec = c.zero, broadcast: c.Vec = c.zero,
     events: std.ArrayList(usize) = .empty, delivered: std.ArrayList(usize) = .empty, hold: std.ArrayList(usize) = .empty,
     next: [6]i64 = .{ 1, 1, 1, 1, 1, 1 }, reorder: [6]std.ArrayList(usize) = [_]std.ArrayList(usize){.empty} ** 6,
     max_held: usize = 0, counts: [5]i64 = .{ 0, 0, 0, 0, 0 } };
pub const EventKind = enum { local, nofunds, send, bcast, recv };
pub const Event = struct { process: usize, local: usize, time: i64, kind: EventKind, peer: ?usize = null,
     message: ?usize = null, copy: ?usize = null, lamport: i64, balance: i64, amount: i64 = 0,
     clock: c.Vec, label: []const u8 = "" };
pub const Message = struct { source: usize, send: usize = 0, tag: []const u8, amount: i64,
     broadcast: bool, stamp: c.Vec = c.zero, copies: std.ArrayList(usize) = .empty };
pub const Copy = struct { message: usize, source: usize, destination: usize, packet: usize = 0,
     received: ?usize = null, delivery: i64 = 0, fifo_wait: bool = false, causal_wait: bool = false,
     missing: []const usize = &.{} };
pub const Packet = struct { source: usize, destination: usize, sequence: i64, dispatch: i64,
     arrival: i64, copy: ?usize = null, snapshot: ?usize = null };
fn parseAction(row: []const []const u8) Action {
    const kinds = [_]ActionKind{ .local, .send, .transfer, .broadcast, .snapshot };
    const names = [_][]const u8{ "LOCAL", "SEND", "TRANSFER", "BROADCAST", "SNAPSHOT" };
    for (names, kinds) |name, kind| if (c.eq(name, row[0])) return .{ .kind = kind, .argument = row[1],
         .tag = if (kind == .send) row[2] else "", .amount = if (kind == .transfer) c.number(row[2]) else 0 };
    unreachable;
}
pub fn load(io: std.Io, topology: c.Topology) ![]Script {
    const scripts = c.alloc(Script, topology.names.len);
    @memset(scripts, .{});
    var current: usize = 0;
    for (try c.readLines(io, "input/programs.txt")) |line| {
        const row = c.words(line);
        if (c.eq(row[0], "PROCESS")) {
            current = topology.index(row[1]);
            scripts[current].balance = c.number(row[3]);
        } else if (c.eq(row[0], "AT")) {
            const repeated = c.eq(row[2], "EVERY");
            c.append(Timed, &scripts[current].at, .{ .start = c.number(row[1]), .period = if (repeated) c.number(row[3]) else 0,
                 .action = parseAction(row[if (repeated) @as(usize, 4) else 2..]) });
        } else if (c.eq(row[0], "ON")) c.append(Rule, &scripts[current].on, .{ .tag = row[1],
             .action = parseAction(row[2..]) });
    }
    return scripts;
}
pub fn initialize(scripts: []const Script) []Process {
    const out = c.alloc(Process, scripts.len);
    for (scripts, out) |script, *state| state.* = .{ .initial = script.balance, .balance = script.balance,
         .minimum = script.balance };
    return out;
}
pub const Scheduled = struct { time: i64, process: usize, action: Action };
pub fn expand(scripts: []const Script, end: i64) []const Scheduled {
    var out: std.ArrayList(Scheduled) = .empty;
    for (scripts, 0..) |script, p| for (script.at.items) |item| {
        var time = item.start;
        while (time <= end) : (time += item.period) {
            c.append(Scheduled, &out, .{ .time = time, .process = p, .action = item.action });
            if (item.period == 0) break;
        }
    };
    return out.items;
}
pub fn balanceAtCut(process: Process, events: []const Event, count: i64) i64 {
    return if (count == 0) process.initial else events[process.events.items[c.u(count - 1)]].balance;
}

const std = @import("std");
const c = @import("network.zig");
const p = @import("processes.zig");
pub const Record = struct { present: bool = false, time: i64 = 0, reason: []const u8 = "",
     balance: i64 = 0, lamport: i64 = 0, clock: c.Vec = c.zero, pending: []const usize = &.{} };
pub const Channel = struct { sent: i64 = 0, accepted: ?i64 = null, copies: std.ArrayList(usize) = .empty };
pub const Ignored = struct { process: usize, time: i64 };
pub const Snapshot = struct { name: []const u8, start: i64, complete: i64 = 0, accepted: usize = 0,
     records: []Record, channels: []Channel, ignored: std.ArrayList(Ignored) = .empty };
pub fn init(name: []const u8, time: i64, count: usize) *Snapshot {
    const records = c.alloc(Record, count);
    @memset(records, .{});
    const channels = c.alloc(Channel, count * count);
    @memset(channels, .{});
    return c.create(Snapshot, .{ .name = name, .start = time, .records = records, .channels = channels });
}
pub fn recordState(snapshot: *Snapshot, process: usize, state: p.Process, time: i64, reason: []const u8) void {
    snapshot.records[process] = .{ .present = true, .time = time, .reason = reason, .balance = state.balance,
         .lamport = state.lamport, .clock = state.clock, .pending = c.dupe(usize, state.hold.items) };
}
pub fn acceptMarker(snapshot: *Snapshot, source: usize, destination: usize, time: i64, count: usize) void {
    snapshot.channels[source * count + destination].accepted = time;
    snapshot.accepted += 1;
    if (snapshot.accepted == count * (count - 1)) snapshot.complete = time;
}
pub fn cut(snapshot: *const Snapshot) c.Vec {
    var out = c.zero;
    for (snapshot.records, 0..) |record, i| out[i] = record.clock[i];
    return out;
}
pub const Details = struct { orphans: std.ArrayList(usize) = .empty, transit: std.ArrayList(usize) = .empty,
     balances: i64 = 0, money: i64 = 0 };
pub fn details(values: c.Vec, processes: []const p.Process, events: []const p.Event, messages: []const p.Message,
     copies: []const p.Copy) Details {
    var out: Details = .{};
    for (copies, 0..) |copy, i| {
        const message = messages[copy.message];
        const sent = c.n(events[message.send].local) <= values[copy.source];
        const received = if (copy.received) |index| c.n(events[index].local) <= values[copy.destination] else false;
        if (received and !sent) c.append(usize, &out.orphans, i);
        if (sent and !received) {
            c.append(usize, &out.transit, i);
            out.money += message.amount;
        }
    }
    for (processes, 0..) |process, i| out.balances += p.balanceAtCut(process, events, values[i]);
    out.money += out.balances;
    return out;
}
